from functools import singledispatch

@singledispatch
def evaluate(node):                       # one operation, one function
    raise NotImplementedError(type(node).__name__)

@evaluate.register
def _(node: Num) -> float: return node.value

@evaluate.register
def _(node: Add) -> float: return evaluate(node.left) + evaluate(node.right)
# the elements stay untouched: @dataclass Num(value), @dataclass Add(left, right)

